using System;
using Godot;

namespace IdleLineage.App;

public static class GameCursorManager
{
	private static bool _initialized;
	private static ImageTexture? _cursorDefault;
	private static ImageTexture? _cursorAttack;
	private static ImageTexture? _cursorDrag;
	private static ImageTexture? _cursorNpc;
	private static ImageTexture? _cursorScroll;

	private const string CursorDefaultB64 = "";
	private const string CursorAttackB64 = "";
	private const string CursorDragB64 = "";
	private const string CursorNpcB64 = "";
	private const string CursorScrollB64 = "";

	public static void Init()
	{
		if (_initialized)
		{
			return;
		}
		_initialized = true;

		_cursorDefault = CreateTexture(CursorDefaultB64);
		_cursorAttack = CreateTexture(CursorAttackB64);
		_cursorDrag = CreateTexture(CursorDragB64);
		_cursorNpc = CreateTexture(CursorNpcB64);
		_cursorScroll = CreateTexture(CursorScrollB64);

		// 1. Default in-game cursor: Image 1 (Gauntlet pointer)
		if (_cursorDefault != null)
		{
			Input.SetCustomMouseCursor(_cursorDefault, Input.CursorShape.Arrow, new Vector2(2f, 0f));
			Input.SetCustomMouseCursor(_cursorDefault, Input.CursorShape.PointingHand, new Vector2(2f, 0f));
		}

		// 2. Attack monster cursor: Image 2 (Sword with target reticle cross at tip)
		if (_cursorAttack != null)
		{
			Input.SetCustomMouseCursor(_cursorAttack, Input.CursorShape.Help, new Vector2(25f, 24f));
		}

		// 3. Move/drag item cursor: Image 3 (Hand holding item)
		if (_cursorDrag != null)
		{
			Input.SetCustomMouseCursor(_cursorDrag, Input.CursorShape.Drag, new Vector2(7f, 2f));
			Input.SetCustomMouseCursor(_cursorDrag, Input.CursorShape.CanDrop, new Vector2(7f, 2f));
		}

		// 4. Visit/interact NPC cursor: Image 4 (Talking lips/mouth)
		if (_cursorNpc != null)
		{
			Input.SetCustomMouseCursor(_cursorNpc, Input.CursorShape.Vsplit, new Vector2(16f, 15f));
		}

		// 5. Use weapon/armor scroll cursor: Image 5 (Magnifying glass/scroll enchanter)
		if (_cursorScroll != null)
		{
			Input.SetCustomMouseCursor(_cursorScroll, Input.CursorShape.Hsplit, new Vector2(14f, 9f));
		}

		// Note: Skill casting keeps original crosshair: Input.CursorShape.Cross is NOT overridden.

		SetDefault();
	}

	public static void SetDefault()
	{
		Input.SetDefaultCursorShape(Input.CursorShape.Arrow);
	}

	public static void SetAttack()
	{
		Input.SetDefaultCursorShape(Input.CursorShape.Help);
	}

	public static void SetDrag()
	{
		Input.SetDefaultCursorShape(Input.CursorShape.Drag);
	}

	public static void SetNpc()
	{
		Input.SetDefaultCursorShape(Input.CursorShape.Vsplit);
	}

	public static void SetScroll()
	{
		Input.SetDefaultCursorShape(Input.CursorShape.Hsplit);
	}

	public static void SetSkillCross()
	{
		Input.SetDefaultCursorShape(Input.CursorShape.Cross);
	}

	private static ImageTexture? CreateTexture(string base64)
	{
		try
		{
			byte[] buffer = Convert.FromBase64String(base64);
			Image image = new Image();
			if (image.LoadPngFromBuffer(buffer) == Error.Ok)
			{
				return ImageTexture.CreateFromImage(image);
			}
		}
		catch (Exception ex)
		{
			GD.PrintErr("[GameCursorManager] Failed to load cursor texture: " + ex.Message);
		}
		return null;
	}
}
